# Dialecte de Selected Track Control, traduit en OSC — GÉNÉRÉ, ne pas éditer.
#   régénérer :  python3 tools/gen_stc_map.py
#
# Mêmes numéros de note et de CC que les réglages par défaut de STC : on retire STC,
# on charge ce fichier, et le contrôleur n'a pas bougé d'un pouce. Le retour d'état
# en plus, qui est ce que STC n'a jamais su faire.
#
# Couverture vérifiée contre l'AbletonOSC installé :
#    34 traduites a la main   +     2 reconnues automatiquement
#    22 rendues par un GESTE (boucles, bascules, navigation relative)
#    10 gestes restants (inversions, rotations de routage, devices)
#    57 sans équivalent dans AbletonOSC (vues, verrouillages, sélections fines)

group   stc
channel 1          # STC parle sur le canal 1 ; les lignes ne le repetent pas
target  127.0.0.1:11000 -> 11001

verb  note 3    arm.exclusive
verb  note 10   arm.kill
verb  note 37   scene.first
verb  note 46   track.first
verb  note 39   scene.last
verb  note 47   track.last
verb  note 5    mute.exclusive
verb  note 8    mute.kill
verb  note 83   scene.next
verb  note 85   track.next
verb  note 40   scene.play_next
verb  note 21   transport.pause
verb  note 36   scene.play_prev
verb  note 20   transport.toggle
verb  note 82   scene.prev
verb  note 84   track.prev
verb  cc   84   scene.scroll
verb  cc   85   track.scroll
verb  note 4    solo.exclusive
verb  note 7    solo.kill
verb  note 88   tempo.down
verb  note 87   tempo.up
send  note 0    /live/track/set/arm $track $a
send  note 117  /live/song/set/arrangement_overdub $a
send  note 13   /live/song/set/back_to_arranger $a
send  note 25   /live/song/set/clip_trigger_quantization $a
send  note 29   /live/song/continue_playing
send  note 69   /live/device/set/parameter/value $track 0 0 $a
send  cc   120  /live/song/set/groove_amount $a.0
send  note 18   /live/song/set/loop $a
send  note 12   /live/song/set/metronome $a
send  note 26   /live/song/set/midi_recording_quantization $a
send  note 2    /live/track/set/mute $track $a
send  note 110  /live/song/set/nudge_down $a
send  note 111  /live/song/set/nudge_up $a
send  note 14   /live/song/set/arrangement_overdub $a
send  cc   23   /live/track/set/panning $track $a
send  note 38   /live/scene/fire_selected
send  note 16   /live/song/set/punch_in $a
send  note 17   /live/song/set/punch_out $a
send  note 19   /live/song/set/record_mode $a
send  note 81   /live/song/redo
send  note 66   /live/view/set/selected_device $a
send  cc   2    /live/view/set/selected_scene $a
send  cc   8    /live/view/set/selected_track $a
send  note 118  /live/song/set/session_record $a
send  note 1    /live/track/set/solo $track $a
send  note 28   /live/song/start_playing
send  note 49   /live/song/stop_all_clips
send  note 27   /live/song/stop_playing
send  note 48   /live/track/stop_all_clips $track
send  note 6    /live/track/set/current_monitoring_state $track $a
send  note 86   /live/song/tap_tempo
send  cc   86   /live/song/set/tempo $a.0
send  note 80   /live/song/undo
send  cc   22   /live/track/set/volume $track $a
send  note 104  /live/song/create_return_track   # auto : create_return_track
send  note 109  /live/song/re_enable_automation   # auto : re_enable_automation

# ══ RETOUR D'ÉTAT — Live vers le contrôleur ════════════════════════════════
# Selected Track Control n'envoie RIEN en retour : c'est ce qui manque depuis
# douze ans. Ces CC sont libres dans son dialecte (les siens s'arrêtent à 52).
watch /live/song/get/is_playing      0  ->  cc 100
watch /live/view/get/selected_scene  0  ->  cc 101
watch /live/song/get/tempo           0  ->  cc 102  $v-50
watch /live/view/get/selected_track  0  ->  cc 103
watch /live/song/get/num_scenes      0  ->  cc 104
watch /live/song/get/num_tracks      0  ->  cc 105
watch /live/song/get/metronome       0  ->  cc 106
watch /live/song/get/record_mode     0  ->  cc 107
watch /live/song/get/loop            0  ->  cc 108

# Ce que le MIDI ne peut pas porter part dans state.json.
text  /live/song/get/track_names  ->  tracks
text  /live/song/get/scenes/name  ->  scenes
